      "key": "card:note-rules-feel-and-formalism",
      "entity_type": "card",
      "title": "规则、手感与形式化设计",
      "subtitle": "阅读笔记",
      "summary": "规则、手感与形式化设计",
      "phase_group": "art-ui-experience",
